,[10,6],[11,3],[11,7],[12,2],[12,8],[13,2],[13,8],[14,5],[16,0],[16,1],[17,0],[17,1],[18,0],[18,1],[20,3],[20,4],[20,5],[21,2],[21,6],[22,2],[22,6],[24,1],[24,2],[24,3],[24,4],[24,5],[24,6],[24,7],[25,5],[26,4],[26,5],[26,6],[32,2],[32,4],[33,3],[34,3],[35,3],[36,4],[36,6],[37,5],[38,5],[39,4],[39,4],[40,4],[39,3],[40,3],[50,4],[51,5],[50,6],[51,6],[52,5],[53,4],[54,5],[55,5],[57,4],[58,5],[57,6],[58,6],[50,7],[51,8],[52,9],[53,9],[54,10],[55,10],[53,11],[54,10],[55,10]]};const cells=patterns[pattern];const offsetY=Math.floor(rows/2)-Math.floor(Math.max(...cells.map(c=>c[0]))/2);const offsetX=Math.floor(cols/2)-Math.floor(Math.max(...cells.map(c=>c[1]))/2);cells.forEach(([dy,dx])=>{const y=offsetY+dy;const x=offsetX+dx;if(y>=0&&y<rows&&x>=0&&x<cols)grid[y][x]=1;});}});canvas.addEventListener('click',e=>{const rect=canvas.getBoundingClientRect();const x=Math.floor((e.clientX-rect.left)/cellSize);const y=Math.floor((e.clientY-rect.top)/cellSize);if(x>=0&&x<cols&&y>=0&&y<rows){grid[y][x]=grid[y][x]===0?1:0;}});function getNeighbors(y,x){let count=0;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(dy===0&&dx===0)continue;const ny=y+dy,nx=x+dx;if(ny>=0&&ny<rows&&nx>=0&&nx<cols)count+=grid[ny][nx]>0?1:0;}return count;}function update(){const newGrid=Array.from({length:rows},()=>Array(cols).fill(0));for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const age=grid[y][x];if(age>0){const neighbors=getNeighbors(y,x);if(neighbors===2||neighbors===3){newGrid[y][x]=age+1;}}else{const neighbors=getNeighbors(y,x);if(neighbors===3){newGrid[y][x]=1;} else if(grid[y][x]>0){dying.push({x,y,alpha:1});}}}grid=newGrid;}function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);ctx.font=`${cellSize}px serif`;ctx.textAlign='center';ctx.textBaseline='middle';for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const age=grid[y][x];if(age>0){for(const e of emojis){if(age<=e.age){ctx.fillText(e.emoji,(x+0.5)*cellSize,(y+0.5)*cellSize);break;}}}dying.forEach((cell,i)=>{ctx.globalAlpha=cell.alpha;ctx.fillText('🟢',(cell.x+0.5)*cellSize,(cell.y+0.5)*cellSize);cell.alpha-=0.05;if(cell.alpha<=0)dying.splice(i,1);});ctx.globalAlpha=1;}function loop(timestamp){if(timestamp-lastUpdate>=genInterval){update();lastUpdate=timestamp;}draw();requestAnimationFrame(loop);}requestAnimationFrame(loop);}

